-- Founder-approved Phase Two journey workbook structure: reuse Phase One store and released-only server gateway.
insert into public.aca_phase_two_workbook_definitions(journey_number,content,version)
values (2,'{"key":"phase-two-journey-two","version":1,"title":"AI Confidence Academy · Phase Two Journey 2 Workbook","navigationLabel":"Journey 2 · Build AI into Business Workflows","subtitle":"Current-state workflow, practical investigation and verified learner notes. Released lessons only.","pageCount":6,"pages":[{"number":1,"lesson_id":"2.1","kicker":"JOURNEY TWO / LESSON 2.1","title":"Map the Work and Locate Friction","blocks":[{"type":"heading","text":"Continue your existing project"},{"type":"text","text":"The Professional AI Operating Model, selected need and FOCUS capstone charter from Journey One provide the starting point. You are not beginning a second project. Use the same Path A or Path B project to understand how its task actually moves through people, information and review."},{"type":"note","title":"Workflow View — seven dimensions","text":"People: who acts or is affected? Inputs: what begins the work and what information is required? Steps: what actions occur? Decisions: what changes direction? Tools: what people actually use now? Handoffs: where work changes hands and who owns it? Review: who checks the result and what does approved completion mean?","theme":"gold"},{"type":"heading","text":"Task, process, workflow and system"},{"type":"text","text":"A task is one action; a process organizes actions; a workflow shows movement, decision branches and handoffs; a system also includes standards, ownership, feedback and continuity. Write the CURRENT state before an ideal future design. Never substitute a polished imagined process for observed or reported steps."},{"type":"field","id":"p2-j2-1-project","label":"Describe the existing Journey One capstone and person served.","hint":"Keep the same FOCUS function, owner, customer, use case and scope.","lines":4},{"type":"field","id":"p2-j2-1-input","label":"What request or event enters the current workflow? Which information is required?","hint":"","lines":4},{"type":"field","id":"p2-j2-1-people","label":"Who starts, handles, receives and reviews the work?","hint":"","lines":4},{"type":"field","id":"p2-j2-1-steps","label":"Trace the current actions in order from entry to reviewed completion.","hint":"Include actual people and decision points.","lines":6},{"type":"field","id":"p2-j2-1-decisions","label":"Where do complete/incomplete inputs, approvals, exceptions or corrections change the path?","hint":"","lines":4},{"type":"field","id":"p2-j2-1-tools","label":"Which tools or approved records are already used? Label unknown systems.","hint":"","lines":4},{"type":"field","id":"p2-j2-1-handoffs","label":"Identify each sending owner, receiving owner, transferred information and next action.","hint":"","lines":4},{"type":"field","id":"p2-j2-1-review","label":"Who checks the final result, what sources are checked and what must be withheld if unsure?","hint":"","lines":4},{"type":"heading","text":"A fictional three-day estimate delay"},{"type":"text","text":"A customer requests an estimate without required specifications. Nobody owns clarification, so the request waits three days. Automating the final email does not fix the wait. Identify the true input-stage handoff and avoid blaming an employee when the problem may be missing responsibility."},{"type":"note","title":"Keep friction evidence honest","text":"Friction includes delay, repeated effort, missing information, inconsistent results and rework. Each claimed cause must be labeled observed, reported, assumed or simulated, and verified against authorized people or records where appropriate.","theme":"gold"},{"type":"field","id":"p2-j2-1-friction1","label":"Friction point 1 — symptom, possible cause, owner, evidence label, source and unanswered question.","hint":"","lines":5},{"type":"field","id":"p2-j2-1-friction2","label":"Friction point 2 — symptom, possible cause, owner, evidence label, source and unanswered question.","hint":"","lines":5},{"type":"field","id":"p2-j2-1-friction3","label":"Friction point 3 — symptom, possible cause, owner, evidence label, source and unanswered question.","hint":"","lines":5},{"type":"heading","text":"Investigate with your own AI assistant"},{"type":"text","text":"Open the AI assistant of your choice on your phone, tablet or computer. Enter only fictional, publicly available, or appropriately sanitized and authorized notes. Ask it to organize YOUR evidence. Do not permit the model to invent workflow steps or treat a guessed cause as a confirmed finding."},{"type":"note","title":"Approved AI request","text":"Organize my verified process notes into people, inputs, steps, decisions, tools, handoffs and review. Flag missing details and possible friction without inventing steps. Notes: [sanitized process].","theme":"gold"},{"type":"field","id":"p2-j2-1-ai-correction","label":"What invented, omitted or unsupported step did the AI propose? How did you correct it?","hint":"","lines":4},{"type":"field","id":"p2-j2-1-verification","label":"How did you verify the current-state map against records, actual practice or a clearly labeled simulation?","hint":"","lines":4},{"type":"heading","text":"Choose one narrow improvement"},{"type":"field","id":"p2-j2-1-improvement","label":"Which friction point will you improve first, and what exactly changes?","hint":"","lines":4},{"type":"field","id":"p2-j2-1-human","label":"Who is responsible for the improved step, review and any exception?","hint":"","lines":4},{"type":"field","id":"p2-j2-1-measure","label":"Which meaningful before/after measure could test whether it helps? What baseline is measured or still unknown?","hint":"","lines":4},{"type":"field","id":"p2-j2-1-trace","label":"Trace one request from entry, through any incomplete-input branch, to human-reviewed completion.","hint":"","lines":5},{"type":"field","id":"p2-j2-1-defend","label":"Explain why your improvement addresses a cause instead of moving the burden or automating an irrelevant later action.","hint":"","lines":4},{"type":"note","title":"Carry your workflow into Lesson 2.2","text":"Save the current-state map, three friction points, evidence labels, corrected AI organization, chosen improvement and request trace in the same continuing Project Record. This study workbook remains yours to review, print or download after release. Lesson 2.2 is locked until its approved schedule.","theme":"gold"}]}]}'::jsonb,1)
